const { AdminService } = require("../services/adminService");

/**
 * Middleware to authenticate Admin tokens
 * Checks bearer token generated by adminLogin
 */
async function authenticateAdminToken(req, res, next) {
  try {
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith("Bearer ")) {
      return res.status(401).json({
        success: false,
        message: "Admin authorization token required (Bearer <token>)",
      });
    }

    const token = authHeader.split(" ")[1];
    if (!token.startsWith("adm_token_")) {
      return res.status(401).json({
        success: false,
        message: "Invalid admin session token format",
      });
    }

    const encodedPart = token.replace("adm_token_", "");
    let decoded;
    try {
      decoded = Buffer.from(encodedPart, "base64").toString("utf8");
    } catch {
      return res.status(401).json({
        success: false,
        message: "Corrupted admin session token",
      });
    }

    const [adminId, email] = decoded.split(":");
    if (!adminId || !email) {
      return res.status(401).json({
        success: false,
        message: "Invalid session claims",
      });
    }

    // Lookup administrator
    let admin = await AdminService.findById(adminId);
    if (!admin) {
      admin = await AdminService.findByEmail(email);
    }

    if (!admin) {
      return res.status(401).json({
        success: false,
        message: "Administrator account no longer exists or access was revoked",
      });
    }

    req.admin = admin;
    next();
  } catch (err) {
    console.error("authenticateAdminToken error:", err);
    return res.status(500).json({
      success: false,
      message: "Server error during admin authentication check",
      error: err.message,
    });
  }
}

module.exports = {
  authenticateAdminToken,
};
